pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount1, uint256 depositAmount2, address actor1, address actor2) public {
        // 1. restrict to admissible inputs: amounts not zero, actors distinct and not the test contract itself
        vm.assume(depositAmount1 > 0);
        vm.assume(depositAmount2 > 0);
        vm.assume(actor1 != actor2);
        vm.assume(actor1 != address(this));
        vm.assume(actor2 != address(this));
        vm.assume(actor1 != address(c));
        vm.assume(actor2 != address(c));
        // 2. fund and deposit for both actors
        vm.deal(actor1, depositAmount1);
        vm.prank(actor1);
        (bool d1,) = address(c).call{value: depositAmount1}("");
        require(d1);
        vm.deal(actor2, depositAmount2);
        vm.prank(actor2);
        (bool d2,) = address(c).call{value: depositAmount2}("");
        require(d2);
        // snapshot total balance across both actors before withdrawal
        uint256 totalBefore = c.balances(actor1) + c.balances(actor2);
        // actor1 withdraws
        vm.prank(actor1);
        c.withdraw();
        // actor2 withdraws
        vm.prank(actor2);
        c.withdraw();
        // snapshot total balance after both withdrawals
        uint256 totalAfter = c.balances(actor1) + c.balances(actor2);
        // the total sum of recorded balances must be strictly less than the sum before withdrawals (funds moved out)
        assertTrue(totalAfter < totalBefore);
    }
}

