pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        ReentrancyAttacker attacker = new ReentrancyAttacker(c);
        address attackerAddr = address(attacker);

        // set up initial balance for the attacker in C
        vm.deal(attackerAddr, amount);
        vm.prank(attackerAddr);
        (bool okDep, ) = address(c).call{value: amount}("");
        require(okDep, "deposit failed");

        // attacker triggers withdraw
        vm.prank(attackerAddr);
        bool ok = false;
        try c.withdraw() { ok = true; } catch { ok = false; }
        // if withdraw reverted, balance must remain unchanged
        if (!ok) {
            assertEq(c.balances(attackerAddr), amount);
            return;
        }

        // after a non-reverting top-level withdraw, the caller's balance must be zero
        uint256 finalBal = c.balances(attackerAddr);
        assertEq(finalBal, 0);
    }
}

contract ReentrancyAttacker {
    C public target;
    bool private reentered;

    constructor(C _target) {
        target = _target;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter withdraw and then deposit back some ETH
            target.withdraw();
            uint256 eth = address(this).balance;
            if (eth > 0) {
                (bool s,) = address(target).call{value: eth}("");
                require(s);
            }
            reentered = false;
        }
    }
}

