pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);

        // Fund the actor and deposit into the contract
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        // First withdraw: should succeed
        vm.prank(actor);
        c.withdraw();

        // The contract must have released the lock.
        // To verify, we send enough ether for a second withdraw and then attempt it.
        // If the lock is stuck, the second withdraw will revert.
        vm.deal(actor, withdrawAmount);
        vm.prank(actor);
        (bool depositOk2, ) = address(c).call{value: withdrawAmount}("");
        require(depositOk2, "second deposit failed");

        vm.prank(actor);
        bool secondWithdrawOk;
        try c.withdraw() { secondWithdrawOk = true; } catch { secondWithdrawOk = false; }

        // Assert: the second withdraw must succeed (lock properly released).
        assertTrue(secondWithdrawOk);
    }
}

